class Solution {
public:
    string decodeAtIndex(string s, int k) {
        long long size = 0;
        int n = (int)s.size();
        for (int i = 0; i < n; i++) {
            if (s[i] >= '0' && s[i] <= '9') {
                size *= (long long)(s[i] - '0');
            } else {
                size += 1;
            }
        }
        long long kk = (long long)k;
        for (int i = n - 1; i >= 0; i--) {
            kk %= size;
            if (kk == 0 && s[i] >= 'a' && s[i] <= 'z') {
                return string(1, s[i]);
            }
            if (s[i] >= '0' && s[i] <= '9') {
                size /= (long long)(s[i] - '0');
            } else {
                size -= 1;
            }
        }
        return "";
    }
};
